mapper.select:
SELECT provinceId, cityId, countyId, tenantId, tenantName, device_code, warning_source, algorithm_code, warning_type_id, sum( not_open_alarm_num ) AS not_open_alarm_num, sum( not_open_judge_num ) AS not_open_judge_num, sum( not_open_real_alarm_num ) AS not_open_real_alarm_num, sum( not_open_false_alarm_num ) AS not_open_false_alarm_num, dateTime, yearStr, monthStr, dayStr FROM ( SELECT aa.province_code AS provinceId, aa.city_code AS cityId, aa.county_code AS countyId, aa.tenant_id AS tenantId, aa.tenant_name AS tenantName, aa.device_code, aa.warning_source, aa.algorithm_code, jt.sub_type AS warning_type_id, SUM( IF ( aa.judge_type = '0' or aa.judge_type IS NULL , 1, 0 ) ) AS not_open_alarm_num, '0' AS not_open_judge_num, '0' AS not_open_real_alarm_num, '0' AS not_open_false_alarm_num, DATE_FORMAT( aa.alarm_time, '%Y-%m-%d' ) AS dateTime, year(aa.alarm_time) yearStr, month(aa.alarm_time) monthStr, day(aa.alarm_time) dayStr FROM ${tableName} aa LEFT JOIN JSON_TABLE( IF(aa.sub_scenes IS NULL OR JSON_TYPE(aa.sub_scenes)='NULL' OR JSON_LENGTH(aa.sub_scenes)=0, JSON_ARRAY(aa.warning_type_id), aa.sub_scenes), '$[*]' COLUMNS (sub_type VARCHAR(64) PATH '$') ) jt ON TRUE WHERE aa.delete_flag = '0'
and DATE_FORMAT( aa.alarm_time, '%Y-%m-%d') = #{handleDate}
AND DATE_FORMAT( aa.alarm_time, '%Y-%m' ) = #{handleDate}
and warning_source IN ('1','12') AND aa.algorithm_code IS NOT NULL AND aa.algorithm_code != '' AND aa.algorithm_code != 'null' GROUP BY aa.province_code, aa.city_code, aa.county_code, aa.warning_source, aa.device_code, aa.algorithm_code, jt.sub_type, aa.tenant_id, aa.tenant_name, dateTime UNION ALL SELECT aa.province_code AS provinceId, aa.city_code AS cityId, aa.county_code AS countyId, aa.tenant_id AS tenantId, aa.tenant_name AS tenantName, aa.device_code, aa.warning_source, aa.algorithm_code, jt.sub_type AS warning_type_id, '0' AS not_open_alarm_num, SUM( IF ( aa.judge_type = '0' or aa.judge_type IS NULL, 1, 0 ) ) AS not_open_judge_num, SUM( IF ( (aa.judge_type = '0' or aa.judge_type IS NULL) AND aa.judge_result IN ( '1', '2' ), 1, 0 ) ) AS not_open_real_alarm_num, SUM( IF ( (aa.judge_type = '0' or aa.judge_type IS NULL) AND aa.judge_result = '0', 1, 0 ) ) AS not_open_false_alarm_num, DATE_FORMAT( aa.judge_time, '%Y-%m-%d' ) AS dateTime, year(aa.judge_time) yearStr, month(aa.judge_time) monthStr, day(aa.judge_time) dayStr FROM ${tableName} aa LEFT JOIN JSON_TABLE( IF(aa.sub_scenes IS NULL OR JSON_TYPE(aa.sub_scenes)='NULL' OR JSON_LENGTH(aa.sub_scenes)=0, JSON_ARRAY(aa.warning_type_id), aa.sub_scenes), '$[*]' COLUMNS (sub_type VARCHAR(64) PATH '$') ) jt ON TRUE WHERE aa.delete_flag = '0'
and DATE_FORMAT( aa.judge_time, '%Y-%m-%d') = #{handleDate}
AND DATE_FORMAT( aa.judge_time, '%Y-%m' ) = #{handleDate}
and warning_source IN ('1','12') AND aa.algorithm_code IS NOT NULL AND aa.algorithm_code != '' AND aa.algorithm_code != 'null' GROUP BY aa.province_code, aa.city_code, aa.county_code, aa.warning_source, aa.device_code, aa.algorithm_code, jt.sub_type, aa.tenant_id, aa.tenant_name, dateTime ) a GROUP BY provinceId, cityId, countyId, tenantId, tenantName, device_code, warning_source, algorithm_code, warning_type_id, dateTime

select province_id , city_id, county_id , tenant_id, tenant_name, device_code, warning_source, algorithm_code, warning_type_id, dateTime, yearStr, monthStr, dayStr, SUM(serial_alarm_num) serial_alarm_num, SUM(parallel_alarm_num) parallel_alarm_num, SUM(serial_judge_num) serial_judge_num, SUM(parallel_judge_num) parallel_judge_num, SUM(serial_real_alarm_num) serial_real_alarm_num, SUM(parallel_real_alarm_num) parallel_real_alarm_num, SUM(serial_false_alarm_num) serial_false_alarm_num, SUM(parallel_false_alarm_num) parallel_false_alarm_num from ( SELECT aa.province_id , aa.city_id, aa.county_id , aa.tenant_id, aa.tenant_name, aa.device_code, aa.warning_source, aa.algorithm_code, jt.sub_type AS warning_type_id, DATE_FORMAT( aa.alarm_time, '%Y-%m-%d' ) AS dateTime, year(aa.alarm_time) yearStr, month(aa.alarm_time) monthStr, day(aa.alarm_time) dayStr, SUM(IF (aa.operate_type = '1',1,0)) AS serial_alarm_num, SUM(IF (aa.operate_type = '2',1,0)) AS parallel_alarm_num, '0' as serial_judge_num, '0' as parallel_judge_num, '0' as serial_real_alarm_num, '0' as parallel_real_alarm_num, '0' as serial_false_alarm_num, '0' as parallel_false_alarm_num FROM vm_alarm_operate_t aa LEFT JOIN ${tableName} ord ON aa.warning_order_id = ord.warning_order_id LEFT JOIN JSON_TABLE( IF(aa.sub_scenes IS NOT NULL AND JSON_TYPE(aa.sub_scenes)!='NULL' AND JSON_LENGTH(aa.sub_scenes)>0, aa.sub_scenes, IF(ord.sub_scenes IS NULL OR JSON_TYPE(ord.sub_scenes)='NULL' OR JSON_LENGTH(ord.sub_scenes)=0, JSON_ARRAY(aa.warning_type_id), ord.sub_scenes)), '$[*]' COLUMNS (sub_type VARCHAR(64) PATH '$') ) jt ON TRUE WHERE aa.delete_flag = '0' and aa.warning_source IN ('1','12')
and DATE_FORMAT( aa.alarm_time, '%Y-%m-%d') = #{handleDate}
AND DATE_FORMAT( aa.alarm_time, '%Y-%m' ) = #{handleDate}
AND aa.algorithm_code IS NOT NULL AND aa.algorithm_code !='' AND aa.algorithm_code !='null' GROUP BY aa.province_id,aa.city_id,aa.county_id, aa.warning_source, aa.device_code,aa.algorithm_code,jt.sub_type,aa.tenant_id,aa.tenant_name,dateTime union all SELECT aa.province_id , aa.city_id, aa.county_id , aa.tenant_id, aa.tenant_name, aa.device_code, aa.warning_source, aa.algorithm_code, jt.sub_type AS warning_type_id, DATE_FORMAT( aa.judge_time, '%Y-%m-%d' ) AS dateTime, year(aa.judge_time) yearStr, month(aa.judge_time) monthStr, day(aa.judge_time) dayStr, '0' AS serial_alarm_num, '0' AS parallel_alarm_num, SUM(IF (aa.operate_type = '1',1,0)) as serial_judge_num, SUM(IF (aa.operate_type = '2',1,0)) as parallel_judge_num, SUM(IF (aa.operate_type = '1' and aa.judge_result = '1',1,0)) as serial_real_alarm_num, SUM(IF (aa.operate_type = '2' and aa.judge_result in ('1','2'),1,0)) as parallel_real_alarm_num, SUM(IF (aa.operate_type = '1' and aa.judge_result = '0',1,0)) as serial_false_alarm_num, SUM(IF (aa.operate_type = '2' and aa.judge_result = '0',1,0)) as parallel_false_alarm_num FROM vm_alarm_operate_t aa LEFT JOIN ${tableName} ord ON aa.warning_order_id = ord.warning_order_id LEFT JOIN JSON_TABLE( IF(aa.sub_scenes IS NOT NULL AND JSON_TYPE(aa.sub_scenes)!='NULL' AND JSON_LENGTH(aa.sub_scenes)>0, aa.sub_scenes, IF(ord.sub_scenes IS NULL OR JSON_TYPE(ord.sub_scenes)='NULL' OR JSON_LENGTH(ord.sub_scenes)=0, JSON_ARRAY(aa.warning_type_id), ord.sub_scenes)), '$[*]' COLUMNS (sub_type VARCHAR(64) PATH '$') ) jt ON TRUE WHERE aa.delete_flag = '0' and aa.warning_source IN ('1','12')
and DATE_FORMAT( aa.judge_time, '%Y-%m-%d') = #{handleDate}
AND DATE_FORMAT( aa.judge_time, '%Y-%m' ) = #{handleDate}
AND aa.algorithm_code IS NOT NULL AND aa.algorithm_code !='' AND aa.algorithm_code !='null' GROUP BY aa.province_id,aa.city_id,aa.county_id, aa.warning_source, aa.device_code,aa.algorithm_code,jt.sub_type,aa.tenant_id,aa.tenant_name,dateTime ) a group by province_id ,city_id,county_id ,tenant_id,tenant_name,device_code,warning_source,algorithm_code,warning_type_id,dateTime

